import{_ as o,o as n,c as s,a6 as r}from"./chunks/framework.O8w_gp-L.js";const c=JSON.parse('{"title":"Controls: keyboard and phone","description":"","frontmatter":{},"headers":[],"relativePath":"guides/controls.md","filePath":"guides/controls.md"}'),a={name:"guides/controls.md"};function e(l,t,i,g,d,h){return n(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="controls-keyboard-and-phone" tabindex="-1">Controls: keyboard and phone <a class="header-anchor" href="#controls-keyboard-and-phone" aria-label="Permalink to &quot;Controls: keyboard and phone&quot;">​</a></h1><p>On a keyboard, right after you make your hero, the <strong>Choose your keys</strong> card lets you pick <strong>Arrow keys</strong> or <strong>WASD</strong>. You can switch any time in <strong>Settings → Controls → Keys</strong>.</p><p><strong>Arrow keys</strong> (the default)</p><ul><li><strong>← →</strong> move · <strong>↑ ↓</strong> aim combo moves</li><li><strong>Space</strong> jump, press again in the air to <strong>double jump</strong></li><li><strong>Shift</strong> attack · <strong>X</strong> dash</li><li><strong>Z</strong> use (talk, take, help a friend). With nothing to use, <strong>Z</strong> guards.</li><li><strong>Q W E R / A S D F</strong> skills · <strong>1–4</strong> items</li></ul><h2 id="wasd" tabindex="-1">WASD <a class="header-anchor" href="#wasd" aria-label="Permalink to &quot;WASD&quot;">​</a></h2><ul><li><strong>A / D</strong> move · <strong>W / S</strong> aim · <strong>Space</strong> jump</li><li><strong>Click</strong> or <strong>J</strong> attack · <strong>Shift</strong> dash</li><li><strong>G</strong> or <strong>right click</strong> use and guard</li><li><strong>Q E R F / Z X C V</strong> skills · <strong>1–4</strong> items</li></ul><h2 id="menu-keys" tabindex="-1">Menu keys <a class="header-anchor" href="#menu-keys" aria-label="Permalink to &quot;Menu keys&quot;">​</a></h2><ul><li><strong>C</strong> Character (Arrow keys only), <strong>K</strong> Skills, <strong>B</strong> or <strong>I</strong> the Bag</li><li><strong>M</strong> opens the chapter map · <strong>Esc</strong> pauses</li><li><strong>Enter</strong> presses a card&#39;s main button</li><li>Opening a menu stops your walking, but the world keeps moving.</li></ul><h2 id="hold-to-attack" tabindex="-1">Hold to attack <a class="header-anchor" href="#hold-to-attack" aria-label="Permalink to &quot;Hold to attack&quot;">​</a></h2><p>Hold Attack and you keep attacking at your weapon&#39;s pace. It is on by default (<strong>Hold Attack to repeat</strong> in Settings). Holding never attacks faster than tapping.</p><h2 id="phone-and-tablet" tabindex="-1">Phone and tablet <a class="header-anchor" href="#phone-and-tablet" aria-label="Permalink to &quot;Phone and tablet&quot;">​</a></h2><p>Phone controls are new and may change.</p><ul><li><strong>Move pad</strong> bottom left, with your four potions beside it.</li><li><strong>Auto</strong>, <strong>Guard</strong>, <strong>Dash</strong>, <strong>Jump</strong> and <strong>Attack</strong> on the right. <strong>Auto</strong> keeps attacking for you; skills stay yours to tap.</li><li>Skill buttons sit on pages <strong>I</strong> and <strong>II</strong> on phones. Tablets show all eight.</li><li>Tap a potion to drink it. Hold it to choose what goes there.</li><li><strong>Settings → Controls → Arrange controls:</strong> move and resize buttons or whole groups. Each screen shape keeps its own layout.</li><li><strong>Left-handed controls</strong> (Settings → Display) mirrors the buttons and pad.</li></ul>',13)])])}const p=o(a,[["render",e]]);export{c as __pageData,p as default};
